function timedOut(state, ctx) {
  // No usable answer by the deadline: the shop accepts the risk and the order is cleared just after it (R2.2). The
  // clearing is anchored at the deadline, so R3.1 and R4.1 run their windows from D, exclusive of it. The wake-up
  // fires at D + 30 min, so every step taken because of the clearing is taken after D.
  const next = { ...state, state: 'cleared', at: state.deadline };
  return { output: view(next), state: next };
}

